function mrdiyJSONDetails(title,value){const d=mrdiyEl('details',undefined,'mrdiy-details');d.append(mrdiyEl('summary',title),mrdiyEl('pre',JSON.stringify(value,null,2)));return d;}
function mrdiyLink(text,url){const a=mrdiyEl('a',text);const safe=safeURL(url);if(safe){a.href=safe;a.target='_blank';a.rel='noopener noreferrer';}return a;}
async function mrdiyLoad(force=false){if(mrdiyUI.data&&!force)return mrdiyUI.data;if(mrdiyUI.promise&&!force)return mrdiyUI.promise;mrdiyUI.promise=request('/api/mrdiy/scenario').then(data=>{if(!data.snapshot?.cases?.length)throw Error('The synthetic scenario is unavailable.');mrdiyUI.data=data;return data;}).finally(()=>mrdiyUI.promise=null);return mrdiyUI.promise;}
