// Optional daily learning sandbox. Heavy work stays in one cancellable dedicated Worker.
const mrdiyLearningUI={tab:'episode',seed:400000,iterations:32,calibration:null,nextDate:'2026-09-25',episode:null,episodeKey:null,update:null,dynamics:null,dynamicsKey:null,benchmark:null,benchmarkError:null,loadingBenchmark:false,active:null,sequence:0,message:'',error:null,render:null,open:false,selectedPolicy:'cover_thermal_myopic_v1'};
const mrdiyLearningPolicyNames={no_action:'No additional action',practical_heuristic:'Legacy practical rule',cover_thermal_myopic_v1:'Calibrated cover + myopic control',trained_tabular_q:'Trained tabular Q policy',observation_history_mcts:'Observation-history MCTS'};
function mrdiyLearningNumber(v){return typeof v==='number'&&Number.isFinite(v)?v.toPrecision(6):'Unavailable';}
function mrdiyLearningKey(){return JSON.stringify({seed:mrdiyLearningUI.seed,iterations:mrdiyLearningUI.iterations,calibration:mrdiyLearningUI.calibration?.version??'shipped-trained-model',event:typeof mrdiyLearningBackdropKey==='function'?mrdiyLearningBackdropKey():null});}
function mrdiyLearningCancel(message='Calculation cancelled.'){const active=mrdiyLearningUI.active;if(!active)return;active.worker.terminate();clearTimeout(active.timer);mrdiyLearningUI.active=null;mrdiyLearningUI.sequence++;mrdiyLearningUI.message=message;mrdiyLearningUI.render?.();}
function mrdiyLearningNavigation(view){if(mrdiyLearningUI.active&&(view!=='strategy'||mrdiyLearningUI.active.caseId!==mrdiyUI.selected))mrdiyLearningCancel('Calculation stopped when you left this scenario.');}
function mrdiyLearningStart(task){
 if(mrdiyLearningUI.active)return;
 if(task==='episode'&&typeof mrdiyLearningBackdropValid==='function'&&!mrdiyLearningBackdropValid()){mrdiyLearningUI.error='Confirm the fictional exposure and a bounded arrival delay before running this backdrop.';mrdiyLearningUI.render?.();return;}
 if(typeof Worker!=='function'){mrdiyLearningUI.error='This browser cannot start a dedicated Worker. Existing deterministic comparisons remain available.';mrdiyLearningUI.render?.();return;}
 const request_id='learning-'+(++mrdiyLearningUI.sequence),key=mrdiyLearningKey(),caseId=mrdiyUI.selected,args={request_id,task,seed:mrdiyLearningUI.seed,iterations:mrdiyLearningUI.iterations,...(mrdiyLearningUI.calibration?{calibration:mrdiyLearningUI.calibration}:{}),...(task==='update'?{new_observed_date:mrdiyLearningUI.nextDate}:{}),...(task==='search'&&typeof mrdiyVisualUI!=='undefined'?{observation:mrdiyVisualUI.searchObservation}:{}),...(task==='episode'&&typeof mrdiyBackdropUI!=='undefined'&&mrdiyBackdropUI.selected?{event_assumption:{event_id:mrdiyBackdropUI.selected,additional_arrival_days:Number(mrdiyBackdropUI.delay),mapping_confirmed:true,impact_confirmed:true}}:{})};
 let worker;try{worker=new Worker('/simulation/learning-task-worker.js',{type:'module'});}catch(error){mrdiyLearningUI.error='The local calculation Worker could not start: '+error.message;mrdiyLearningUI.render?.();return;}
 const active={worker,request_id,key,caseId,task,timer:null};mrdiyLearningUI.active=active;mrdiyLearningUI.message='Starting the dedicated calculation Worker…';mrdiyLearningUI.error=null;
 function finish(){clearTimeout(active.timer);worker.terminate();if(mrdiyLearningUI.active===active)mrdiyLearningUI.active=null;}
 worker.onmessage=event=>{const msg=event.data;if(mrdiyLearningUI.active!==active||msg?.request_id!==request_id)return;if(state.view!=='strategy'||mrdiyUI.selected!==caseId||key!==mrdiyLearningKey()){finish();mrdiyLearningUI.message='Discarded a result for inputs that changed.';mrdiyLearningUI.render?.();return;}
  if(msg.status==='progress'){const p=msg.progress||{};mrdiyLearningUI.message=(p.phase||'Computing')+(p.policy?' · '+(mrdiyLearningPolicyNames[p.policy]||p.policy):'')+(Number.isFinite(p.completed_days)?' · '+p.completed_days+'/'+p.total_days+' daily transitions':Number.isFinite(p.completed)?' · '+p.completed+'/'+p.total:'');mrdiyLearningUI.render?.();return;}
  finish();if(msg.status!=='ok'||!msg.result){mrdiyLearningUI.error='Calculation unavailable: '+(msg.error||'No validated result was returned.');mrdiyLearningUI.render?.();return;}
  if(task==='episode'){if(typeof mrdiyVisualUI!=='undefined'){mrdiyVisualUI.search=null;mrdiyVisualUI.searchKey=null;}mrdiyLearningUI.episode=msg.result;mrdiyLearningUI.episodeKey=key;}
  if(task==='dynamics'){mrdiyLearningUI.dynamics=msg.result;mrdiyLearningUI.dynamicsKey=key;}if(task==='search'&&typeof mrdiyVisualUI!=='undefined'){mrdiyVisualUI.search=msg.result;mrdiyVisualUI.searchKey=key+'|'+args.observation?.day;}if(task==='backtest'&&typeof mrdiyVisualUI!=='undefined')mrdiyVisualUI.backtest=msg.result;
  if(task==='update'&&!msg.result.after?.calibration?.version){mrdiyLearningUI.error='The model update returned no valid fitted version.';mrdiyLearningUI.render?.();return;}
  if(task==='update'){if(typeof mrdiyVisualUI!=='undefined'){mrdiyVisualUI.search=null;mrdiyVisualUI.searchKey=null;}mrdiyLearningUI.update=msg.result;mrdiyLearningUI.calibration=msg.result.after.calibration;mrdiyLearningUI.nextDate=new Date(Date.parse(args.new_observed_date+'T00:00:00Z')+86400000).toISOString().slice(0,10);}
  mrdiyLearningUI.message='Calculation completed locally. No operational action was executed.';mrdiyLearningUI.render?.();if(task==='episode'&&typeof mvFocus==='function')mvFocus('.mv-result-heading');
 };
 worker.onerror=()=>{if(mrdiyLearningUI.active!==active)return;finish();mrdiyLearningUI.error='The calculation Worker failed. Retry or keep using the existing comparisons.';mrdiyLearningUI.render?.();};
 active.timer=setTimeout(()=>{if(mrdiyLearningUI.active===active){mrdiyLearningCancel('Stopped at the 30-second calculation budget.');mrdiyLearningUI.error='This device did not complete within the bound. Try the 32-iteration setting.';mrdiyLearningUI.render?.();}},30000);
 try{worker.postMessage(args);}catch(error){finish();mrdiyLearningUI.error='The bounded request could not be sent to its Worker: '+error.message;}mrdiyLearningUI.render?.();
}
async function mrdiyLearningLoadBenchmark(){if(mrdiyLearningUI.benchmark||mrdiyLearningUI.loadingBenchmark)return;mrdiyLearningUI.loadingBenchmark=true;try{mrdiyLearningUI.benchmark=await request('/simulation/heldout-summary.json');mrdiyLearningUI.benchmarkError=null;}catch(error){mrdiyLearningUI.benchmarkError='Saved heldout report unavailable. A single episode is not performance validation.';}finally{mrdiyLearningUI.loadingBenchmark=false;mrdiyLearningUI.render?.();}}
